    /// <summary>
    /// Find the record
    /// </summary>
    /// <param name="_metPOCostExcSecRole"> Get security role</param>
    /// <param name="_forupdate"> Get update parameter </param>
    /// <param name="_concurrencyModel"> Get concurrency model parameter </param>
    ///  <returns>
    /// Return table record
    /// </returns>
    static METPOCostUpdateExceptionUserRoles find(METPOCostExcSecRole _metPOCostExcSecRole, boolean _forupdate = false, ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METPOCostUpdateExceptionUserRoles metPOCostUpdateExceptionUserRoles;

        metPOCostUpdateExceptionUserRoles.selectForUpdate(_forupdate);
        metPOCostUpdateExceptionUserRoles.concurrencyModel(_concurrencyModel);

        select firstonly metPOCostUpdateExceptionUserRoles
            where metPOCostUpdateExceptionUserRoles.MetPOCostExcSecRole == _metPOCostExcSecRole;
         
        return metPOCostUpdateExceptionUserRoles;
    }

