    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs    
    /// This clears the cache object in purchase order lines
    /// </summary>
    /// <returns>
    /// A boolean value
    /// </returns>
    public static NoYes checkUserExceptionDefined()
    {
        
        SecurityUserRole                    securityUserRole;
        UserInfo                            userInfo;
        SecurityRole                        securityRole;
        METPOCostUpdateExceptionUserRoles   metPOCostUpdateExceptionUserRoles;      
              
        select Name from securityRole
            exists join securityUserRole
                where securityUserRole.SecurityRole == securityRole.RecId
            exists join userInfo
                where userInfo.id == securityUserRole.User
                &&    userInfo.id == curUserId()
            exists join metPOCostUpdateExceptionUserRoles
            where metPOCostUpdateExceptionUserRoles.MetPOCostExcSecRole == securityRole.Name;
        if(securityRole.Name)
        {
            return true;
        }

        return false;
    }
